def sum_digits(n: int) -> int:
    n = abs(n)
    if n < 10:
        return n
    return (n % 10) + sum_digits(n // 10)

def reverse_string_rec(s: str) -> str:
    if len(s) <= 1:
        return s
    return reverse_string_rec(s[1:]) + s[0]

def apply_multiplier(factor: int, val: int) -> int:
    def make_multiplier(f):
        return lambda x: x * f
    multiplier = make_multiplier(factor)
    return multiplier(val)

def curry_multiply(a: int, b: int) -> int:
    curried = lambda x: lambda y: x * y
    return curried(a)(b)

def gcd_recursive(a: int, b: int) -> int:
    if b == 0:
        return a
    return gcd_recursive(b, a % b)

def fib_memo(n: int) -> int:
    memo = {0: 0, 1: 1}
    def helper(k):
        if k not in memo:
            memo[k] = helper(k - 1) + helper(k - 2)
        return memo[k]
    return helper(n)

def compose_two(x: int) -> int:
    f = lambda n: n + 3
    g = lambda n: n * 2
    return g(f(x))

def collatz_steps(n: int) -> int:
    steps = 0
    while n > 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        steps += 1
    return steps

def manage_bank_account(initial: int, deposits: list[int], withdrawals: list[int]) -> int:
    class BankAccount:
        def __init__(self, bal):
            self.bal = bal
        def deposit(self, amt):
            self.bal += amt
        def withdraw(self, amt):
            if self.bal >= amt:
                self.bal -= amt
    acc = BankAccount(initial)
    for d in deposits:
        acc.deposit(d)
    for w in withdrawals:
        acc.withdraw(w)
    return acc.bal

def calculate_rectangle(w: float, h: float) -> dict:
    class Rectangle:
        def __init__(self, width, height):
            self.width = width
            self.height = height
        def area(self):
            return self.width * self.height
        def perimeter(self):
            return 2 * (self.width + self.height)
    r = Rectangle(w, h)
    return {'area': r.area(), 'perimeter': r.perimeter()}

def format_book(title: str, author: str, year: int) -> str:
    class Book:
        def __init__(self, t, a, y):
            self.t, self.a, self.y = t, a, y
        def __str__(self):
            return f'{self.t} by {self.a} ({self.y})'
    return str(Book(title, author, year))

def convert_temp_static(c: float) -> float:
    class TemperatureConverter:
        @staticmethod
        def c_to_f(val):
            return round(val * 9.0 / 5.0 + 32.0, 1)
    return TemperatureConverter.c_to_f(c)

def evaluate_car_hierarchy(brand: str, model: str, battery_kwh: int) -> str:
    class Vehicle:
        def __init__(self, brand, model):
            self.brand = brand
            self.model = model
    class ElectricCar(Vehicle):
        def __init__(self, brand, model, battery_kwh):
            super().__init__(brand, model)
            self.battery_kwh = battery_kwh
        def get_info(self):
            return f'{self.brand} {self.model} with {self.battery_kwh}kWh battery'
    car = ElectricCar(brand, model, battery_kwh)
    return car.get_info()

def add_vectors(x1: int, y1: int, x2: int, y2: int) -> list[int]:
    class Vector:
        def __init__(self, x, y):
            self.x, self.y = x, y
        def __add__(self, other):
            return Vector(self.x + other.x, self.y + other.y)
    v3 = Vector(x1, y1) + Vector(x2, y2)
    return [v3.x, v3.y]

def simulate_stack(ops: list[str]) -> list:
    class Stack:
        def __init__(self):
            self._items = []
        def push(self, x):
            self._items.append(x)
        def pop(self):
            return self._items.pop() if self._items else None
    s = Stack()
    for op in ops:
        if op.startswith('push '):
            s.push(op.split(' ')[1])
        elif op == 'pop':
            s.pop()
    return s._items

def calculate_shape_areas(shapes: list[dict]) -> list[float]:
    class Circle:
        def __init__(self, r):
            self.r = r
        def area(self):
            return round(3.14159 * self.r * self.r, 2)
    class Square:
        def __init__(self, s):
            self.s = s
        def area(self):
            return round(self.s * self.s, 2)
    out = []
    for item in shapes:
        if item['type'] == 'circle':
            out.append(Circle(item['val']).area())
        elif item['type'] == 'square':
            out.append(Square(item['val']).area())
    return out

def track_employee_count(names: list[str]) -> int:
    class Employee:
        count = 0
        def __init__(self, name):
            self.name = name
            Employee.count += 1
        @classmethod
        def get_count(cls):
            return cls.count
    for n in names:
        Employee(n)
    return Employee.get_count()

def simulate_queue(ops: list[str]) -> list:
    class Queue:
        def __init__(self):
            self._q = []
        def enqueue(self, val):
            self._q.append(val)
        def dequeue(self):
            return self._q.pop(0) if self._q else None
    q = Queue()
    for op in ops:
        if op.startswith('enqueue '):
            q.enqueue(op.split(' ')[1])
        elif op == 'dequeue':
            q.dequeue()
    return q._q
